def logout(conn):
    if st.session_state.get("user"):
        audit(conn, "LOGOUT", "usuarios", st.session_state.user["id"], "Cierre de sesión")
    st.session_state.clear()
    st.rerun()


def login_ui(conn):
    """Pantalla de acceso con alto contraste y mensajes visibles.

    Los campos se mantienen como widgets nativos de Streamlit para no afectar
    el autocompletado ni la accesibilidad del navegador.
    """
    st.markdown(
        """<div class="tmq-login-shell"><div class="tmq-login-head">
        <img src="data:image/png;base64,""" + LOGO_FULL_B64 + """">
        <div class="tmq-login-title">Control de Calidad Analítico</div>
        <div class="tmq-login-sub">Westgard · Levey–Jennings · Trazabilidad</div>
        </div></div>""",
        unsafe_allow_html=True,
    )

    _, center, _ = st.columns([1, 1.15, 1])
    with center:
        with st.form("login_form", clear_on_submit=False, border=True):
            st.markdown("#### Iniciar sesión")
            username = st.text_input(
                "Usuario",
                placeholder="Ej.: DRM",
                autocomplete="username",
            )
            password = st.text_input(
                "Contraseña",
                type="password",
                placeholder="Ingresa tu contraseña",
                autocomplete="current-password",
            )
            submitted = st.form_submit_button(
                "Ingresar",
                type="primary",
                use_container_width=True,
            )

        if submitted:
            if not username.strip() or not password:
                st.error("Ingresa tu usuario y contraseña.")
            else:
                try:
                    user, msg = authenticate(conn, username, password)
                    if user:
                        st.session_state.user = user
                        st.rerun()
                    st.error(msg or "No fue posible iniciar sesión.")
                except Exception as exc:
                    # No exponer secretos de BD; sí mostrar un mensaje útil.
                    st.error("No fue posible validar las credenciales. Intenta nuevamente.")
                    st.caption(f"Detalle técnico: {type(exc).__name__}")

        st.markdown(
            '<div class="tmq-login-help">Acceso individual y trazable. '
            'Los eventos críticos quedan registrados en auditoría. '
            'Si la cuenta fue bloqueada por intentos fallidos, espera 15 minutos o solicita apoyo a un Administrador.</div>',
            unsafe_allow_html=True,
        )

def forced_password_change_ui(conn, user: dict):
    st.warning("Debes cambiar tu contraseña antes de continuar.")
    with st.form("forced_password"):
        p1 = st.text_input("Nueva contraseña", type="password")
        p2 = st.text_input("Repetir contraseña", type="password")
